export const BlurRevealText = ({ text = 'Build with ElementraUI' }) => {
  const words = text.split(' ');
  return (
    <h1 className="text-3xl font-extrabold text-white flex flex-wrap gap-2">
      {words.map((word, i) => (
        <motion.span
          key={i}
          initial={{ opacity: 0, filter: 'blur(10px)', y: 8 }}
          animate={{ opacity: 1, filter: 'blur(0px)', y: 0 }}
          transition={{ duration: 0.6, delay: i * 0.15 }}
        >
          {word}
        </motion.span>
      ))}
    </h1>
  );
};

