import React, { useState } from 'react';

export const PomodoroTimer = () => {
  const [seconds, setSeconds] = useState(1500);
  const [running, setRunning] = useState(false);
  const mins = Math.floor(seconds / 60);
  const secs = seconds % 60;
  return (
    <div className="p-6 bg-slate-950 rounded-2xl border border-slate-800 text-center max-w-xs mx-auto">
      <div className="text-4xl font-mono font-extrabold text-cyan-400 mb-4">
        {String(mins).padStart(2, '0')}:{String(secs).padStart(2, '0')}
      </div>
      <button
        onClick={() => setRunning(!running)}
        className="px-5 py-2 rounded-xl bg-cyan-500 text-slate-950 font-bold text-xs hover:bg-cyan-400"
      >
        {running ? 'Pause' : 'Start Focus'}
      </button>
    </div>
  );
};
